using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitInquiryTests
{
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:unit-inquiry/"+s.Revision+"/"+a),a);
    static void Send(WorldSession s,NewMilitaryAction a,long amount=0){var r=s.DecideNewMilitary(Input(s,a) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
    static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
    static WorldSession Ready(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Send(s,NewMilitaryAction.Request);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);At(s,ArmyEnd(s)+1);return s;}
    static long ArmyEnd(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.Max(r=>r.LastOrDefault()?.EndAt??s.Seconds);
    static WorldSession Failed(bool known=true){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();At(s,d.DueAt);Assert.False(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().Delivered);if(known)At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt);return s;}
    static WorldSession HomeReady(){var s=Ready();Send(s,NewMilitaryAction.Recall);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,Math.Max(ArmyEnd(s),j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);return s;}
    static TroopDispatch Query(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();
    static TroopReceipt Answer(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Receipts.Last();
    static UnitPostInquiryAnswer Quote(ContractWorld w){var r=w.NewMilitary!.UnitInquiry!.Receipts.Last();return ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body));}
    [Fact]public void InquiryWithNoOriginalRegistersOnlyAnonymousRoles(){var s=HomeReady();var before=s.DiagnosticSnapshot();Send(s,NewMilitaryAction.InquireUnitHome);At(s,Query(s).DueAt);At(s,Answer(s).ReplyDueAt);var w=s.DiagnosticSnapshot();Assert.Empty(w.NewMilitary!.Withdrawal!.Dispatches);Assert.Empty(Quote(w).Originals);Assert.Equal(before.Characters.Length,w.Characters.Length);Assert.Equal(ContractJson.CanonicalHash(before.Definitions),ContractJson.CanonicalHash(w.Definitions));Assert.False(Answer(s).Applied);Assert.Equal(40,Quote(w).Soldiers);}
    [Fact]public void QuoteIsUnknownBeforePhysicalReturn(){var s=HomeReady();Send(s,NewMilitaryAction.InquireUnitHome);Assert.Contains("未受領",NewGameMilitary.UnitInquiryStatus(s.DiagnosticSnapshot()));At(s,Query(s).DueAt);Assert.Contains("未受領",NewGameMilitary.UnitInquiryStatus(s.DiagnosticSnapshot()));var r=Answer(s);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,r.ReplyMessage,s.PlayerControl.Value));At(s,r.ReplyDueAt);Assert.Contains("40人",NewGameMilitary.UnitInquiryStatus(s.DiagnosticSnapshot()));}
    [Fact]public void UnreceivedQuoteDoesNotBecomeFailureKnowledge(){var s=Failed(false);var original=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();Send(s,NewMilitaryAction.InquireUnitHome);At(s,Query(s).DueAt);At(s,Answer(s).ReplyDueAt);var w=s.DiagnosticSnapshot();Assert.False(Quote(w).Originals.Single().Received);Assert.False(MessageFlow.FailureKnown(w.Messaging,original.Attempt,w.PlayerControl.Value));Assert.False(NewGameMilitary.UnitRetryAllowed(w,NewMilitaryAction.RetryRecallHome));Assert.False(MessageFlow.Knows(w.Messaging,original.Message,w.PlayerControl.Value));}
    [Fact]public void AppliedCommandQuoteDoesNotCreateSenderOriginalReceipt(){var s=Ready();Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);var j=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last();At(s,(j.Route.LastOrDefault()?.EndAt??s.Seconds)+1);Send(s,NewMilitaryAction.RemoteRecall);var d=s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Single();At(s,d.DueAt);At(s,Math.Max(ArmyEnd(s),s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Receipts.Single().ReplyDueAt)+1);Send(s,NewMilitaryAction.InquireUnitHome);At(s,Query(s).DueAt);At(s,Answer(s).ReplyDueAt);var w=s.DiagnosticSnapshot();var q=Quote(w).Originals.Single();Assert.True(q.Received);Assert.True(q.Applied);Assert.Single(w.Messaging.Receipts,r=>r.MessageId==d.Message&&r.PrincipalId==d.Recipient.Value);Assert.False(MessageFlow.Knows(w.Messaging,d.Message,w.PlayerControl.Value));}
    [Fact]public void ReplyRemainsFixedWhenUnitMovesAfterWriting(){var s=HomeReady();Send(s,NewMilitaryAction.InquireUnitHome);At(s,Query(s).DueAt);var r=Answer(s);var w=s.DiagnosticSnapshot();string body=w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body;var home=NewGameMilitary.Home(w,0);Send(s,NewMilitaryAction.Attach);var a=NewGameMilitary.Anchor(w);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+30000,a.Y),B=new(a.X+30000,a.Y+16000)},s.PlayerControl,s.Revision).Code);Send(s,NewMilitaryAction.Withdraw);At(s,r.ReplyDueAt);w=s.DiagnosticSnapshot();Assert.Equal(body,w.Messaging.Messages.Single(m=>m.Id==r.ReplyMessage).Body);Assert.True(Quote(w).AtHome);Assert.Equal(home,Quote(w).Position);Assert.NotEqual(home,NewGameMilitary.Position(w,0,s.Seconds));}
    [Fact]public void InquiryReplyMissesDepartedSender(){var s=HomeReady();Send(s,NewMilitaryAction.InquireUnitHome);var home=NewGameMilitary.Home(s.DiagnosticSnapshot(),0);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(home.X+5000,home.Y)},s.PlayerControl,s.Revision).Code);At(s,Query(s).DueAt);At(s,Answer(s).ReplyDueAt);var w=s.DiagnosticSnapshot();Assert.False(w.NewMilitary!.UnitInquiry!.Replies.Last().Received);Assert.Contains("未受領",NewGameMilitary.UnitInquiryStatus(w));}
    [Fact]public void KnownDestinationDoesNotFollowMissingReceiver(){var s=HomeReady();Send(s,NewMilitaryAction.InquireUnitKnown);var d=Query(s);Assert.Equal(s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Sightings.Last().Position,d.Destination);At(s,d.DueAt);Assert.False(Answer(s).Delivered);At(s,Answer(s).ReplyDueAt);Assert.Contains("会えなかった",NewGameMilitary.UnitInquiryStatus(s.DiagnosticSnapshot()));}
    [Fact]public void DuplicateQuestionDoesNotMakeAnotherEnvelope(){var s=HomeReady();var i=Input(s,NewMilitaryAction.InquireUnitHome);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(i,s.PlayerControl,0).Code);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void RestoredInquiryHasSameFuture(int step){var s=HomeReady();Send(s,NewMilitaryAction.InquireUnitHome);if(step>0)At(s,Query(s).DueAt);if(step>1)At(s,Answer(s).ReplyDueAt);if(step>2)At(s,s.Seconds+2);var c=new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));long until=s.Seconds+3;foreach(var x in new[]{s,c})At(x,until);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(c.DiagnosticSnapshot()));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ForgedQuotedWorldIsRejected(int kind){var s=HomeReady();Send(s,NewMilitaryAction.InquireUnitHome);At(s,Query(s).DueAt);At(s,Answer(s).ReplyDueAt);var w=s.DiagnosticSnapshot();var r=Answer(s);var q=Quote(w);if(kind<4){q=kind switch{0=>q with{Soldiers=999},1=>q with{Position=new(0,0)},2=>q with{At=q.At+1},_=>q with{Originals=[new("invented",true,true,0)]}};w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==r.ReplyMessage?m with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(q))}:m).ToArray();}else{var d=Query(s);var m=w.Messaging.Messages.Single(m=>m.Id==d.Message);var request=ContractJson.Read<UnitPostInquiry>(System.Text.Encoding.UTF8.GetBytes(m.Body));w.Messaging.Messages=w.Messaging.Messages.Select(t=>t.Id==m.Id?t with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(request with{Originals=[d.Message]}))}:t).ToArray();}Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldSaveOmitsInquiryExtension(){var s=HomeReady();string text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot().NewMilitary));Assert.DoesNotContain("UnitInquiry",text);Assert.Null(ContractJson.Read<NewMilitaryState>(System.Text.Encoding.UTF8.GetBytes(text)).UnitInquiry);}
}
